// test_decoder_tb.sv -- standalone unit test for decoder.sv
//
// decoder.sv is pure combinational, so this needs no clock and no pipeline:
// drive an instruction word, check every field. Vectors come from
// testbenches/decoder_vectors.svh, generated by
// python_scripts/gen_decoder_vectors.py -- see that file for how the expected
// values are derived (from assembly source text, not by re-slicing the word).

`timescale 1ns/1ps

module test_decoder_tb;

    `include "tb_check.svh"
    `include "decoder_vectors.svh"

    logic [31:0] instr;
    logic [6:0]  opcode;
    logic [4:0]  rd, rs1, rs2;
    logic [2:0]  funct3;
    logic [6:0]  funct7;
    logic [31:0] imm;

    decoder dut (.*);

    initial begin
        $display("== test_decoder: %0d directed vectors ==", N_DVEC);

        for (int v = 0; v < N_DVEC; v++) begin
            instr = DVEC_INSTR[v];
            #1;  // pure combinational -- just let it settle

            `CHECK_EQ($sformatf("%-20s opcode", DVEC_NAME[v]), opcode, DVEC_OPCODE[v])
            `CHECK_EQ($sformatf("%-20s imm",    DVEC_NAME[v]), imm,    DVEC_IMM[v])

            if (DVEC_MASK[v] & F_RD)
                `CHECK_EQ($sformatf("%-20s rd",     DVEC_NAME[v]), rd,     DVEC_RD[v])
            if (DVEC_MASK[v] & F_RS1)
                `CHECK_EQ($sformatf("%-20s rs1",    DVEC_NAME[v]), rs1,    DVEC_RS1[v])
            if (DVEC_MASK[v] & F_RS2)
                `CHECK_EQ($sformatf("%-20s rs2",    DVEC_NAME[v]), rs2,    DVEC_RS2[v])
            if (DVEC_MASK[v] & F_F3)
                `CHECK_EQ($sformatf("%-20s funct3", DVEC_NAME[v]), funct3, DVEC_F3[v])
            if (DVEC_MASK[v] & F_F7)
                `CHECK_EQ($sformatf("%-20s funct7", DVEC_NAME[v]), funct7, DVEC_F7[v])
        end

        // An unrecognised opcode must produce imm == 0 rather than X: cpu.sv
        // and pc.sv both consume imm unconditionally, so an X here would
        // propagate into the datapath on any garbage word (e.g. running off
        // the end of a program into zeroed memory).
        instr = 32'h0000_0000;
        #1;
        `CHECK_EQ("all-zero word -> imm 0", imm, 32'd0)
        instr = 32'hFFFF_FF7F;   // opcode 0x7F, not a real RV32I opcode
        #1;
        `CHECK_EQ("unknown opcode -> imm 0", imm, 32'd0)

        `TB_SUMMARY("test_decoder")
    end

endmodule
